.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  border: 0;
}
.sr-only-focusable:active,
.sr-only-focusable:focus {
  position: static;
  width: auto;
  height: auto;
  margin: 0;
  overflow: visible;
  clip: auto;
}
.squares-clear {
  clear: both;
}
.squares-element {
  box-sizing: border-box;
  -moz-box-sizing: border-box;
  -webkit-box-sizing: border-box;
}
.squares-element > * {
  margin: 0;
}
.squares-element img,
.squares-element video {
  max-width: 100%;
  display: block;
}
.squares-button {
  text-decoration: none;
  text-align: center;
}
.squares-button:hover {
  filter: brightness(1.1);
  -moz-filter: brightness(1.1);
  -webkit-filter: brightness(1.1);
}
.squares-button:active {
  filter: brightness(0.9);
  -moz-filter: brightness(0.9);
  -webkit-filter: brightness(0.9);
}
.squares-container {
  width: 100%;
  display: flex;
  flex-wrap: wrap;
}
@media (min-width: 576px) {
  .squares-container {
    max-width: 540px;
  }
}
@media (min-width: 768px) {
  .squares-container {
    max-width: 720px;
  }
}
@media (min-width: 992px) {
  .squares-container {
    max-width: 960px;
  }
}
@media (min-width: 1200px) {
  .squares-container {
    max-width: 1140px;
  }
}
